const r = await tools.exec_command({cmd:"python3 - <<'PY'
import joblib, numpy as np
from pathlib import Path
from sklearn.metrics import f1_score, roc_auc_score, average_precision_score
from scipy.optimize import linear_sum_assignment
mods={p.stem.split('_')[0]:joblib.load(p) for p in Path('artifacts').glob('*_eng.joblib')}
y=next(iter(mods.values()))['y']; classes=next(iter(mods.values()))['classes']
rng=np.random.default_rng(42)

def assign(p,n=50,kind='log'):
 if kind=='log': score=np.log(np.clip(p,1e-10,1))
 elif kind=='raw': score=p
 elif kind=='logit': score=np.log(np.clip(p,1e-8,1-1e-8))-np.log(np.clip(1-p,1e-8,1))
 elif kind=='rank':
  score=np.empty_like(p)
  for k in range(p.shape[1]): score[np.argsort(p[:,k]),k]=np.linspace(0,1,len(p),endpoint=False)
 slots=np.repeat(np.arange(6),n)
 rr,cc=linear_sum_assignment(-score[:,slots])
 out=slots[cc[np.argsort(rr)]]
 return out
samples=[]
for rep in range(200):
 idx=np.concatenate([rng.choice(np.flatnonzero(y==k),50,replace=False) for k in range(6)])
 rng.shuffle(idx); samples.append(idx)
print('Model metrics and balanced assignment mean/std over 200 draws:')
for name,d in mods.items():
 p=d['oof']
 auc=np.mean([roc_auc_score(y==k,p[:,k]) for k in range(6)])
 ap=np.mean([average_precision_score(y==k,p[:,k]) for k in range(6)])
 vals=[]
 for kind in ['log','raw','logit','rank']:
  z=[f1_score(y[idx],assign(p[idx],kind=kind),average='macro') for idx in samples]
  vals.append(f'{kind} {np.mean(z):.4f}')
 print(f'{name:7s} auc={auc:.4f} ap={ap:.4f}',*vals)
# blends geometric and arithmetic
sets=[['lgb','lgb2'],['lgb','xgb'],['lgb','lgb2','xgb'],['lgb','lgb2','xgb','et'],['lgb','lgb2','xgb','svc'],['lgb','lgb2','xgb','et','rf','svc'],list(mods)]
print('\nBlends')
for names in sets:
 for method in ['arith','geom']:
  if method=='arith': p=sum(mods[n]['oof'] for n in names)/len(names)
  else: p=np.exp(sum(np.log(np.clip(mods[n]['oof'],1e-9,1)) for n in names)/len(names)); p/=p.sum(1,keepdims=True)
  z=[f1_score(y[idx],assign(p[idx]),average='macro') for idx in samples]
  print('+'.join(names),method,np.mean(z),np.std(z))
# test quota prediction pairwise agreements under models / blends
print('\nTest quota agreements:')
preds={n:assign(d['test']) for n,d in mods.items()}
for n,v in preds.items(): print(n, ' '.join(classes[v[:0]]), dict(zip(classes,np.bincount(v,minlength=6))))
key=list(preds)
print('       '+' '.join(f'{n:>7}' for n in key))
for a in key: print(f'{a:7}', ' '.join(f'{np.mean(preds[a]==preds[b]):7.3f}' for b in key))
# main blends output disagreement
for names in sets:
 p=sum(mods[n]['test'] for n in names)/len(names); preds['blend_' + str(len(names))]=assign(p)
print('blends agreements final pairs')
for a in list(preds)[-len(sets):]: print(a,[round(np.mean(preds[a]==preds[b]),3) for b in list(preds)[-len(sets):]])
